import { BrevoClient } from "../../src/Client";
import { mockServerPool } from "../mock-server/MockServerPool";
import { mockOauth2 } from "./mockAuth";

describe("OAuthClient", () => {
    test("getOAuthM2MToken", async () => {
        const server = mockServerPool.createServer();
        mockOauth2(server);

        const client = new BrevoClient({
            maxRetries: 0,
            apiKey: { apiKey: "test" },
            oauth2: { clientId: "client_id", clientSecret: "client_secret" },
            environment: { base: server.baseUrl, oAuth: server.baseUrl },
        });
        const rawRequestBody = {
            grant_type: "client_credentials",
            client_id: "client_id",
            client_secret: "client_secret",
        };
        const rawResponseBody = { access_token: "access_token", token_type: "Bearer", expires_in: 1 };

        server
            .mockEndpoint()
            .post("/oauth/token")
            .formUrlEncodedBody(rawRequestBody)
            .respondWith()
            .statusCode(200)
            .jsonBody(rawResponseBody)
            .build();

        const response = await client.oAuth.getOAuthM2MToken({
            client_id: "client_id",
            client_secret: "client_secret",
        });
        expect(response).toEqual(rawResponseBody);
    });
});
